#!/bin/bash
# Writes deploy/install.sh, which carries deploy/setup.sh and the files it
# installs, and puts its hashes in docs/deploy.md. Run it after changing any of
# them; deploy/test fails until then.
set -euo pipefail
cd "$(dirname "$0")/.."

end=FRICT_INSTALL_EOF
{
  cat <<'HEAD'
#!/bin/bash
# Generated by deploy/make-install.sh from deploy/: edit those files and run it.
# docs/deploy.md says how to fetch, check and run this.
set -euo pipefail
umask 077
dir=$(mktemp -d)
trap 'rm -rf "${dir:?}"' EXIT
HEAD
  for f in setup.sh frict-deploy sudoers compose.yaml; do
    if grep -qx "$end" "deploy/$f" || [[ -n $(tail -c 1 "deploy/$f") ]]; then
      echo "deploy/$f must end in a newline and not contain the line $end" >&2
      exit 1
    fi
    printf "cat >\"\$dir/%s\" <<'%s'\n" "$f" "$end"
    cat "deploy/$f"
    echo "$end"
  done
  cat <<'TAIL'
bash "$dir/setup.sh" "$@"
TAIL
} >deploy/install.sh.new
mv deploy/install.sh.new deploy/install.sh

blob=$(git hash-object deploy/install.sh)
sum=$(sha256sum deploy/install.sh | cut -d' ' -f1)
sed -i -E "s|(/git/blobs/)[0-9a-f]{40}|\1$blob|; s|^echo '[0-9a-f]{64}  install.sh'|echo '$sum  install.sh'|" docs/deploy.md
